#include <iostream>
#include <vector>
using namespace std;
int main(){
    ios::sync_with_stdio(false);cin.tie(nullptr);
    int tests;if(!(cin>>tests))return 0;
    while(tests--){
        int n;cin>>n;vector<int> h(n);vector<bool> works(n+1,false);
        for(auto &v:h)cin>>v;
        for(int i=0;i<n;++i)
            if((i>0&&h[i]==h[i-1])||(i>1&&h[i]==h[i-2]))works[h[i]]=true;
        bool first=true;
        for(int v=1;v<=n;++v)if(works[v]){
            if(!first)cout<<' ';cout<<v;first=false;
        }
        if(first)cout<<-1;
        cout<<'\n';
    }
}
