#include <iostream>
#include <vector>
using namespace std;
int main(){
    ios::sync_with_stdio(false);cin.tie(nullptr);
    int n,start;if(!(cin>>n>>start))return 0;
    vector<int> type(n),value(n);vector<long long> seen(2*n,0);
    vector<bool> broken(n,false);
    for(int i=0;i<n;++i)cin>>type[i]>>value[i];
    long long position=start-1,power=1;int direction=1,answer=0;
    while(position>=0&&position<n){
        int key=2*position+(direction>0);
        if(seen[key]==power)break;
        seen[key]=power;
        if(type[position]==0){power+=value[position];direction=-direction;}
        else if(power>=value[position]&&!broken[position]){
            broken[position]=true;++answer;
        }
        position+=direction*power;
    }
    cout<<answer<<'\n';
}
