#include <iostream>
#include <cstdlib>
using namespace std;
int main(){
    ios::sync_with_stdio(false);cin.tie(nullptr);
    int n;if(!(cin>>n))return 0;
    long long previous=0,before_previous=0,answer=0;
    for(int i=0;i<n;++i){
        long long current;cin>>current;
        long long coefficient=-current+2*previous-before_previous;
        answer+=llabs(coefficient);
        before_previous=previous;previous=current;
    }
    cout<<answer<<'\n';
}
